var canvas = document.getElementById(canvasId)
var ctx = canvas.getContext("2d")
var trackImage = new Image()
trackImage.src = "track.png"
var carImage = new Image()
carImage.src = "car.png"
var lap = 0
var bestLap = Infinity
var startTime = 0

// Access microphone
navigator.mediaDevices.getUserMedia({audio: true})
  .then(function(stream) {
    var mediaRecorder = new MediaRecorder(stream)
    mediaRecorder.onstart = function() {-record()}
    mediaRecorder.start()
  })
  .catch(function(err) {console.log(err.name+": "+err.message)})

// Draw race track
function drawTrack() {
  ctx.drawImage(trackImage, 0, 0, canvas.width, canvas.height)
}

// Animate car movement
window.addEventListener("keydown", function(e) {
  if (e.code === "Space") {
    if (!startTime) startTime = performance.now()
    mediaRecorder.start()
  }
})

// Update car position based on microphone volume
function updateCar() {
  mediaRecorder.ondataavailable = function(e) {
    var audioContext = new AudioContext()
    var audioData = audioContext.decodeAudioData(e.data)
    var volume = getRMS(audioData)

    // Map volume to car speed range
    var carSpeed = volume * 10

    // Update car position
    var car = document.getElementById("car")
    car.style.left = car.offsetLeft + carSpeed + "px"
    car.style.top = car.offsetTop + "px"

    // Determine current lap
    if (car.getBoundingClientRect().left > canvas.width) {
      lap++
      document.getElementById("lap").innerText = lap
      mediaRecorder.stop()

      // Update personal best time
      var lapTime = performance.now() - startTime
      if (lapTime < bestLap) {
        bestLap = lapTime
        document.getElementById("best").innerText = bestLap.toFixed(2)
      }

      // Show game over message
      alert("Congratulations! You finished in " + lapTime.toFixed(2) + " seconds with a personal best of " + bestLap.toFixed(2) + " seconds.")
    } else if (car.getBoundingClientRect().bottom > canvas.height || car.getBoundingClientRect().top < 0) {
      // Handle crashing into wall
      alert("Crash! Better luck next time.")
      startTime = 0
      mediaRecorder.stop()
    }
  }
}

// Calculate RMS of audio data
function getRMS(audioData) {
  var sum = 0
  for (var i = 0; i < audioData.length; i++) {
    var value = Math.abs(audioData[i])
    sum += Math.pow(value, 2)
  }
  var rms = Math.sqrt(sum / audioData.length)
  return rms
}

// Start race on button click
document.getElementById("start").addEventListener("click", function() {
  // Start recording audio
  mediaRecorder.start()

  // Reset lap counter
  lap = 0
  document.getElementById("lap").innerText = lap

  // Reset start time
  startTime = 0
})

// Mute/unmute microphone on button click
document.getElementById("mute").addEventListener("click", function() {
  var stream = mediaRecorder.stream
  var audioTracks = stream.getAudioTracks()
  var muted = false
  for (var i = 0; i < audioTracks.length; i++) {
    if (audioTracks[i].enabled) {
      audioTracks[i].enabled = false
      muted = true
    } else {
      audioTracks[i].enabled = true
      muted = false
    }
  }
  this.innerText = muted ? "Unmute" : "Mute"
})

// Draw track and car every frame
function gameLoop() {
  drawTrack()
  updateCar()
  requestAnimationFrame(gameLoop)
}

gameLoop()

Solution B: ```javascript
function createVoiceRace(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = canvas.width, height = canvas.height;
    const trackPadding = 80;
    const track = {
        outer: { x: 0, y: 0, w: width, h: height },
        inner: { x: trackPadding, y: trackPadding, w: width - 2 * trackPadding, h: height - 2 * trackPadding }
    };
    const startLine = { x1: width / 2 - 30, y1: trackPadding, x2: width / 2 + 30, y2: trackPadding };
    const obstacles = [
        { x: width / 2, y: height / 3, r: 20 },
        { x: width / 4, y: (height * 2) / 3, r: 15 },
        { x: (width * 3) / 4, y: (height * 2) / 3, r: 15 }
    ];

    const car = {
        x: width / 2,
        y: height - 100,
        angle: -Math.PI / 2,
        speed: 0,
        radius: 15,
        maxSpeed: 5
    };

    let microphoneStream = null;
    let analyser = null;
    let audioData = new Uint8Array(256);
    let micInput = 0;
    let isMuted = false;
    let isRunning = false;
    let lastLapTime = 0;
    let personalBest = parseFloat(localStorage.getItem('voiceRaceBest')) || Infinity;
    let lapStartTime = null;
    let crash = false;

    const startBtn = document.createElement('button');
    startBtn.textContent = 'Start Race';
    const muteBtn = document.createElement('button');
    muteBtn.textContent = 'Mute';
    startBtn.style.marginRight = '10px';
    document.body.insertBefore(startBtn, canvas);
    document.body.insertBefore(muteBtn, canvas);

    startBtn.onclick = () => {
        if (!isRunning) {
            startRace();
        }
    };
    muteBtn.onclick = () => {
        isMuted = !isMuted;
        muteBtn.textContent = isMuted ? 'Unmute' : 'Mute';
    };

    function startRace() {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return;
        navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => {
            microphoneStream = stream;
            const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            const source = audioCtx.createMediaStreamSource(stream);
            analyser = audioCtx.createAnalyser();
            analyser.fftSize = 256;
            source.connect(analyser);
            isRunning = true;
            lapStartTime = Date.now();
            requestAnimationFrame(update);
        }).catch(err => console.error('Microphone access denied', err));
    }

    function update() {
        if (!isRunning) return;
        ctx.clearRect(0, 0, width, height);
        drawTrack();
        drawObstacles();
        drawStartLine();
        drawCar();
        updateCar();
        drawVolumeMeter();
        drawLapInfo();
        if (crash) showCrash();
        requestAnimationFrame(update);
    }

    function drawTrack() {
        ctx.fillStyle = '#444';
        ctx.fillRect(track.outer.x, track.outer.y, track.outer.w, track.outer.h);
        ctx.fillStyle = '#222';
        ctx.fillRect(track.inner.x, track.inner.y, track.inner.w, track.inner.h);
    }

    function drawObstacles() {
        ctx.fillStyle = '#900';
        obstacles.forEach(o => {
            ctx.beginPath();
            ctx.arc(o.x, o.y, o.r, 0, 2 * Math.PI);
            ctx.fill();
        });
    }

    function drawStartLine() {
        ctx.strokeStyle = '#ff0';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(startLine.x1, startLine.y1);
        ctx.lineTo(startLine.x2, startLine.y2);
        ctx.stroke();
    }

    function drawCar() {
        ctx.save();
        ctx.translate(car.x, car.y);
        ctx.rotate(car.angle);
        ctx.fillStyle = '#0f0';
        ctx.fillRect(-car.radius, -car.radius, car.radius * 2, car.radius * 2);
        ctx.restore();
    }

    function updateCar() {
        getMicLevel();
        const targetSpeed = isMuted ? 0 : micInput * car.maxSpeed;
        car.speed += (targetSpeed - car.speed) * 0.05;
        car.x += car.speed * Math.cos(car.angle);
        car.y += car.speed * Math.sin(car.angle);
        if (checkCollision()) {
            car.speed *= 0.5;
            crash = true;
        }
        handleLap();
    }

    function getMicLevel() {
        if (!analyser) { micInput = 0; return; }
        analyser.getByteTimeDomainData(audioData);
        let sum = 0;
        for (let i = 0; i < audioData.length; i++) sum += (audioData[i] - 128) * (audioData[i] - 128);
        const rms = Math.sqrt(sum / audioData.length) / 128;
        micInput = Math.min(rms * 2, 1);
    }

    function drawVolumeMeter() {
        const meterWidth = 200, meterHeight = 10;
        const x = (width - meterWidth) / 2, y = height - 30;
        ctx.strokeStyle = '#fff';
        ctx.strokeRect(x, y, meterWidth, meterHeight);
        ctx.fillStyle = '#0f0';
        ctx.fillRect(x, y, meterWidth * micInput, meterHeight);
    }

    function drawLapInfo() {
        const now = Date.now();
        const elapsed = ((now - lapStartTime) / 1000).toFixed(2);
        ctx.fillStyle = '#fff';
        ctx.font = '16px sans-serif';
        ctx.fillText(`Lap: ${elapsed}s`, 10, 30);
        ctx.fillText(`Best: ${(personalBest / 1000).toFixed(2)}s`, 10, 50);
    }

    function checkCollision() {
        if (car.x < track.outer.x || car.x > track.outer.x + track.outer.w ||
            car.y < track.outer.y || car.y > track.outer.y + track.outer.h) return true;
        if (car.x > track.inner.x && car.x < track.inner.x + track.inner.w &&
            car.y > track.inner.y && car.y < track.inner.y + track.inner.h) return true;
        for (const o of obstacles) {
            const dx = car.x - o.x, dy = car.y - o.y;
            if (Math.hypot(dx, dy) < car.radius + o.r) return true;
        }
        return false;
    }

    function handleLap() {
        if (car.y <= startLine.y1 && car.prevY > startLine.y1) {
            const now = Date.now();
            const lapTime = now - lapStartTime;
            if (lapTime < personalBest) {
                personalBest = lapTime;
                localStorage.setItem('voiceRaceBest', lapTime);
            }
            lapStartTime = now;
        }
        car.prevY = car.y;
    }

    function showCrash() {
        ctx.fillStyle = 'rgba(255,0,0,0.5)';
        ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = '#fff';
        ctx.font = '48px sans-serif';
        ctx.fillText('Crash!', width / 2 - 70, height / 2 + 20);
    }
}
